#!/usr/bin/env python3
"""Independent byte-level check of the M1 catalog goldens.

Written from the plan and spec text rather than from `catalog.rs`, so it is a second implementation of the
*rules* rather than of the code: a bug in the renderer and a bug in the verifier would have to agree.

Rules encoded (plan Task 9 + controller rulings):
  R1 header: '# INDEX' / '_generated by note-processor; do not edit_' / blank
  R2 entry line: '- [[title]](rel) · size · tags · ->out <-inc'  (arrows U+2192/U+2190, middot U+00B7)
     tags = '#a #b ...' or a single em dash
  R3 size: '<n> B' | '<n>.<d> KB|MB|GB' (one decimal from KB up)
  R4 every line <= 100 chars; continuation lines indented exactly two spaces
  R5 INDEX.md is entry point: shard links only, '- [a-b](INDEX-a-b.md)' with EN DASH in the label
     and ASCII hyphen in the file name; suffix form ' #2' / '-2' allowed for split buckets
  R6 shard entries sorted by (title.casefold(), rel)
  R7 bucket key: first char of casefolded title when ASCII [0-9a-z]; else '#'; order 0-9, a-z, #
     and each file's name range must match its first/last bucket keys
  R8 exactly one trailing newline; no CR anywhere
"""
import re
import sys
import unicodedata
from pathlib import Path

# The repository holding this script, so the check runs from any working directory and on any machine.
REPO = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parents[2]
GOLD = REPO / "tests" / "golden"

ENTRY = re.compile(
    r"^- \[\[(?P<title>.*)\]\]\((?P<rel>[^)]*)\) · (?P<size>\d+ B|\d+\.\d KB|\d+\.\d MB|\d+\.\d GB)"
    r" · (?P<tags>#\S+(?: #\S+)*|—) · →(?P<out>\d+) ←(?P<inc>\d+)$"
)
SHARD_NAME = re.compile(r"^INDEX-([0-9a-z#])-([0-9a-z#])(-\d+)?\.md$")
LINK = re.compile(r"^- \[(?P<a>[0-9a-z#])–(?P<b>[0-9a-z#])(?: #(?P<n>\d+))?\]\((?P<file>INDEX-[0-9a-z#]-[0-9a-z#](?:-\d+)?\.md)\)$")

fail = []
warn = []


def check(cond, msg):
    if not cond:
        fail.append(msg)


def read(name):
    raw = (GOLD / name).read_bytes()
    check(b"\r" not in raw, f"{name}: contains CR byte")
    check(raw.endswith(b"\n") and not raw.endswith(b"\n\n"), f"{name}: must end with exactly one newline")
    return raw.decode("utf-8").split("\n")[:-1]  # drop the empty tail after final \n


def bucket(title):
    c = title.casefold()[:1]
    return c if re.fullmatch(r"[0-9a-z]", c or "") else "#"


def bucket_rank(b):
    if b.isdigit():
        return (0, b)
    if b.isalpha():
        return (1, b)
    return (2, "#")


def columns(s):
    """Display columns, measured the way the renderer measures them: East Asian Wide/Fullwidth count two, combining
    marks count zero. Characters is not a substitute — that is the regression this file exists to catch."""
    n = 0
    for ch in s:
        if unicodedata.combining(ch):
            continue
        n += 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
    return n


def width_ok(pline):
    """R4, with the product's own exemption.

    `wrap` gives a token wider than the columns left on its line a line of its own (`src/catalog.rs`, "The one exemption"),
    so an over-wide physical line is legal exactly when it holds a single token after its indent — which is what a
    space-free CJK title produces, because there is no legal break inside it. Measured here as an upper bound for
    zero-width format characters (ZWJ, ZWSP): `east_asian_width` and `combining` say nothing about category Cf, so such a
    line reads slightly wide. That errs toward flagging, never toward passing, and the fixture keeps ZWJ out anyway.
    """
    return columns(pline) <= 100 or len(pline.strip().split(" ")) == 1


def read_path(path, label):
    raw = path.read_bytes()
    check(b"\r" not in raw, f"{label}: contains CR byte")
    check(raw.endswith(b"\n") and not raw.endswith(b"\n\n"), f"{label}: must end with exactly one newline")
    return raw.decode("utf-8").split("\n")[:-1]


def entries_from(lines, label, start=4):
    """Parse wrapped entry lines out of a generated file, checking R2/R3/R4 and the continuation-indent rule.

    Shared by the sharded goldens and `tests/golden-wide/`, so the two directories cannot be held to different standards:
    a copy of this loop that was allowed to drift is how a golden directory ends up checked by no rule at all.
    """
    entries = []
    i = start
    while i <= len(lines):
        ln = lines[i - 1]
        check(ln.startswith("- "), f"{label}:{i}: expected an entry, found: {ln!r}")
        physical = [ln]
        j = i + 1
        while j <= len(lines) and lines[j - 1].startswith(" "):
            cont = lines[j - 1]
            check(cont.startswith("  ") and not cont.startswith("   "),
                  f"{label}:{j}: continuation indent must be exactly two spaces: {cont[:6]!r}")
            physical.append(cont)
            j += 1
        for k, pline in enumerate(physical):
            check(width_ok(pline),
                  f"{label}:{i + k}: {columns(pline)} columns > 100 and the line holds more than one token")
        logical = physical[0].rstrip() + "".join(" " + p.strip() for p in physical[1:])
        trailing = [k + i for k, p in enumerate(physical) if p != p.rstrip()]
        if trailing:
            warn.append(f"{label}:{trailing}: line ends with whitespace (wrap did not trim before the break)")
        em = ENTRY.match(logical)
        check(bool(em), f"{label}:{i}: not a valid entry (logical): {logical!r}")
        if em:
            entries.append((em.group("title"), em.group("rel")))
        i = j
    return entries


# ---- .gitattributes -------------------------------------------------------
ga = (REPO / ".gitattributes").read_text() if (REPO / ".gitattributes").exists() else ""
check("text=auto" in ga and "eol=lf" in ga, ".gitattributes: missing '* text=auto eol=lf'")
check("/tests/fixtures/** -text" in ga, ".gitattributes: fixtures not exempt (-text)")
check("/tests/golden/** -text" in ga, ".gitattributes: goldens not exempt (-text)")
check("/tests/golden-wide/** -text" in ga, ".gitattributes: the wide goldens are not exempt (-text), so a Windows checkout\n      could rewrite their bytes")

# ---- golden files ---------------------------------------------------------
files = sorted(p.name for p in GOLD.glob("*.md"))
check("INDEX.md" in files, "no INDEX.md entry point")
shards = [f for f in files if f != "INDEX.md"]

lines = read("INDEX.md")
check(lines[:3] == ["# INDEX", "_generated by note-processor; do not edit_", ""],
      f"INDEX.md: header is {lines[:3]!r}")
body = lines[3:]
links = []
for i, ln in enumerate(body, start=4):
    m = LINK.match(ln)
    check(bool(m), f"INDEX.md:{i}: not a shard link: {ln!r}")
    if m:
        links.append((m.group("a"), m.group("b"), m.group("n") or "1", m.group("file")))
        check(m.group("file") in shards, f"INDEX.md:{i}: links to a file that is not present: {m.group('file')}")
        check(not ENTRY.match(ln), f"INDEX.md:{i}: entry line leaked into the entry point")

check(sorted(links and [l[3] for l in links] or []) == sorted(shards),
      f"INDEX.md does not list every shard: linked={sorted(l[3] for l in links)} present={sorted(shards)}")

all_entries = []
for name in shards:
    m = SHARD_NAME.match(name)
    check(bool(m), f"shard file name is not INDEX-<first>-<last>[-N].md: {name}")
    slines = read(name)
    check(slines[:3] == ["# INDEX", "_generated by note-processor; do not edit_", ""],
          f"{name}: header missing (every generated file carries it)")
    # the wrap breaks *before* a token, so rejoining with one space rebuilds the logical line
    entries = entries_from(slines, name)
    check(entries == sorted(entries, key=lambda t: (t[0].casefold(), t[1])),
          f"{name}: entries are not ordered by (lowercased title, rel)")
    if entries:
        first, last = bucket(entries[0][0]), bucket(entries[-1][0])
        want = f"INDEX-{first}-{last}"
        check(name.startswith(want + ".md") or name.startswith(want + "-"),
              f"{name}: name range does not match its buckets ({first}..{last})")
        for title, rel in entries:
            b = bucket(title)
            check(bucket_rank(first) <= bucket_rank(b) <= bucket_rank(last),
                  f"{name}: entry {title!r} (bucket {b}) outside the file's range {first}..{last}")
    all_entries += entries

titles = [(t.casefold(), r) for t, r in all_entries]
check(len(titles) == len(set(titles)), "an entry appears in more than one shard")
check(titles == sorted(titles), "shards, read in name order, are not globally sorted")

# ---- tests/golden-wide: an UNSHARDED entry point ---------------------------
# The M1 corpus above is sharded, so its INDEX.md must hold only shard links (R5) and every entry rule runs over the
# shards. F16's wide fixture renders with the default max_entries_per_file, which produces one INDEX.md **of entries**:
# run through the code above it would either fail "not a shard link" or — if that check were simply relaxed — be read by
# no rule at all while still printing pass. So it gets its own mode: R2/R3/R4/R6 and the byte rules apply, R5 (links) and
# R7 (bucket ranges) cannot, because an unsharded file has neither.
WIDE = REPO / "tests" / "golden-wide"
if not WIDE.exists():
    check(False, "tests/golden-wide/ is missing: the wide-character goldens are part of the corpus")
else:
    got = sorted(p.name for p in WIDE.glob("*.md"))
    check(got == ["INDEX.md"], f"tests/golden-wide holds {got}, expected exactly ['INDEX.md']")
    if got == ["INDEX.md"]:
        wlines = read_path(WIDE / "INDEX.md", "golden-wide/INDEX.md")
        check(wlines[:3] == ["# INDEX", "_generated by note-processor; do not edit_", ""],
              f"golden-wide/INDEX.md: header is {wlines[:3]!r}")
        wentries = entries_from(wlines, "golden-wide/INDEX.md")
        check(wentries == sorted(wentries, key=lambda t: (t[0].casefold(), t[1])),
              "golden-wide/INDEX.md: entries are not ordered by (lowercased title, rel)")
        wide_text = (WIDE / "INDEX.md").read_text(encoding="utf-8")
        check(any(unicodedata.east_asian_width(c) in ("W", "F") for c in wide_text),
              "golden-wide/INDEX.md holds no two-column character: this directory exists to cover wide text")
        check(any(columns(line) != len(line) for line in wide_text.split("\n")),
              "no line of golden-wide/INDEX.md distinguishes columns from characters, so these bytes cannot detect the\n"
              "      regression they were added for")
        print(f"wide entries: {len(wentries)}  (unsharded mode: R2/R3/R4/R6)")

print(f"files: {files}")
print(f"entries across shards: {len(all_entries)}  shard links: {len(links)}")
for w in warn:
    print("WARN " + w)
if fail:
    print("\n".join("FAIL " + f for f in fail))
    print(f"GOLDEN CHECK: fail — {len(fail)} problem(s)")
    sys.exit(1)
print("GOLDEN CHECK: pass")
